import React, { useEffect, useState } from "react";
import axios from "axios";
import AlertBox from "./AlertBox";
import AppShell from "./ui/AppShell";
import StatCard from "./ui/StatCard";
import Panel from "./ui/Panel";
import { FaBookOpen, FaUserTie, FaClock, FaCheckCircle } from "react-icons/fa";
import "./theme.css";

function Courses() {
  const userId = localStorage.getItem("user_id");
  const role = localStorage.getItem("role");

  const [courses, setCourses] = useState([]);
  const [alert, setAlert] = useState(null);
  const [enrolledIds, setEnrolledIds] = useState([]);

  const fetchCourses = async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/courses");
      setCourses(res.data.courses || []);

      if (role === "student") {
        const enrollRes = await axios.get(`http://127.0.0.1:8000/enrollments/${userId}`);
        setEnrolledIds(enrollRes.data.map((e) => e.course_id));
      }
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    fetchCourses();
  }, []);

  const handleEnroll = async (courseId) => {
    try {
      const res = await axios.post("http://127.0.0.1:8000/enroll", {
        user_id: parseInt(userId),
        course_id: courseId
      });

      setAlert({
        message: res.data.message,
        type: "success"
      });

      fetchCourses();
    } catch (err) {
      console.error(err);
      setAlert({
        message: "Enrollment failed",
        type: "error"
      });
    }
  };

  const myEnrolledCount = enrolledIds.length;
  const latestCourse = courses[0];

  return (
    <AppShell
      title="Courses"
      subtitle="Explore all available courses with creator details, subject code, and created time."
    >
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <div className="page-grid-4" style={{ marginBottom: "18px" }}>
        <StatCard
          icon={<FaBookOpen />}
          label="Total Courses"
          value={courses.length}
          hint="Courses currently available"
        />
        <StatCard
          icon={<FaCheckCircle />}
          label={role === "student" ? "My Enrollments" : "Role Access"}
          value={role === "student" ? myEnrolledCount : "Teacher"}
          hint={role === "student" ? "Courses enrolled by you" : "Viewing as teacher"}
          accent="var(--success)"
        />
        <StatCard
          icon={<FaUserTie />}
          label="Latest Creator"
          value={latestCourse ? latestCourse.created_by || "Unknown" : "N/A"}
          hint={latestCourse ? latestCourse.title : "No course data"}
          accent="var(--info)"
        />
        <StatCard
          icon={<FaClock />}
          label="Latest Subject"
          value={latestCourse ? latestCourse.subject_code : "N/A"}
          hint="Most recently added course code"
          accent="var(--warning)"
        />
      </div>

      <Panel title="All Available Courses">
        {courses.length === 0 ? (
          <p className="muted">No courses available.</p>
        ) : (
          <div className="page-grid-3">
            {courses.map((course) => {
              const isEnrolled = enrolledIds.includes(course.id);

              return (
                <div
                  key={course.id}
                  style={{
                    background: "var(--surface)",
                    border: "1px solid var(--border)",
                    borderRadius: "18px",
                    padding: "18px",
                    boxShadow: "var(--shadow-sm)"
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      justifyContent: "space-between",
                      gap: "10px",
                      alignItems: "center"
                    }}
                  >
                    <h4 style={{ margin: 0 }}>{course.title}</h4>
                    <span className="badge badge-purple">{course.subject_code}</span>
                  </div>

                  <div className="muted" style={{ marginTop: "10px", lineHeight: 1.6 }}>
                    {course.description}
                  </div>

                  <div className="muted" style={{ marginTop: "12px" }}>
                    Created By: {course.created_by || "Unknown"}
                  </div>

                  <div className="muted" style={{ marginTop: "6px" }}>
                    Created At:{" "}
                    {course.created_at
                      ? new Date(course.created_at).toLocaleString()
                      : "N/A"}
                  </div>

                  {role === "student" && (
                    <div style={{ marginTop: "14px" }}>
                      {isEnrolled ? (
                        <span className="badge badge-green">Already Enrolled</span>
                      ) : (
                        <button
                          className="btn btn-primary"
                          style={{ width: "100%" }}
                          onClick={() => handleEnroll(course.id)}
                        >
                          Enroll Now
                        </button>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </Panel>
    </AppShell>
  );
}

export default Courses;
